 back:'<path d="m15 5-7 7 7 7"/>', chevron:'<path d="m9 5 7 7-7 7"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>',
 locate:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',
