 star:'<path d="m12 2 3 6.5 7 1-5 5 1.3 7L12 18l-6.3 3.5 1.3-7-5-5 7-1Z"/>',
 phone:'<path d="M5 3h4l2 5-3 2c2 3 3 4 6 6l2-3 5 2v4c0 4-7 2-12-3S2 3 5 3Z"/>',
 message:'<path d="M3 4h18v13H9l-6 4Z"/><path d="M7 9h10M7 13h7"/>',
 send:'<path d="m2 10 20-8-8 20-4-8Z"/><path d="m10 14 12-12"/>',
 refresh:'<path d="M20 11a8 8 0 1 0-2 6M20 4v7h-7"/>',
 light:'<path d="M8 15a7 7 0 1 1 8 0l-1 4H9Z"/><path d="M9 22h6"/>',
