 bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4Z"/><path d="M9 20h6M12 1v2"/>',
 shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',
 shop:'<path d="M4 10v11h16V10M2 10l3-8h14l3 8Z"/><path d="M9 21v-7h6v7M2 10c2 3 4 3 6 0 2 3 4 3 6 0 2 3 5 3 8 0"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
 users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 3a4 4 0 0 1 0 8m2 3c3 1 3 4 3 7"/>',
 plus:'<path d="M12 4v16M4 12h16"/>', check:'<path d="m4 12 5 5L20 6"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',
 logout:'<path d="M9 4H3v16h6m6-16 7 8-7 8m-8-8h15"/>',
 route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h8"/>',
 stairs:'<path d="M2 21h6v-6h6V9h6V3h3"/>', map:'<path d="m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3Zm6-3v17m8-14v17"/>',
 edit:'<path d="m4 16-1 5 5-1L21 7l-4-4Zm10-10 4 4"/>', trash:'<path d="M3 6h18M5 6l1 15h12l1-15M8 6V3h8v3m-6 4v7m4-7v7"/>',
 lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M7 10V6a5 5 0 0 1 10 0v4m-5 5v3"/>',
 flag:'<path d="M5 22V3c4-4 10 4 15 0v11c-5 4-11-4-15 0"/>',
